const body = $json.body ?? {};
const headers = $json.headers ?? {};
const action = String(body.action ?? '').trim();
const key = String(headers['x-schoolpulse-key'] ?? headers['X-SchoolPulse-Key'] ?? body.key ?? '').trim();

const API_KEY = 'SCHOOLPULSE-DEMO-1448';
const store = $getWorkflowStaticData('global');

const pad = n => String(n).padStart(2,'0');
function riyadhNow(){
  const d = new Date(Date.now()+3*60*60*1000);
  return {
    date:`${d.getUTCFullYear()}-${pad(d.getUTCMonth()+1)}-${pad(d.getUTCDate())}`,
    time:`${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())}`,
    stamp:`${d.getUTCFullYear()}${pad(d.getUTCMonth()+1)}${pad(d.getUTCDate())}${pad(d.getUTCHours())}${pad(d.getUTCMinutes())}${pad(d.getUTCSeconds())}`,
    iso:`${d.getUTCFullYear()}-${pad(d.getUTCMonth()+1)}-${pad(d.getUTCDate())} ${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())}`
  };
}
const now = riyadhNow();
function addHours(dateTime,h){
  const d = new Date(dateTime.replace(' ','T')+'+03:00');
  const x = new Date(d.getTime()+h*3600000);
  const y = new Date(x.getTime()+3*3600000);
  return `${y.getUTCFullYear()}-${pad(y.getUTCMonth()+1)}-${pad(y.getUTCDate())} ${pad(y.getUTCHours())}:${pad(y.getUTCMinutes())}`;
}
function gen(prefix){return `${prefix}-${now.stamp}-${Math.random().toString(36).slice(2,5).toUpperCase()}`;}
function event(type,ref,description,user='النظام'){
  store.events.unshift({id:gen('EV'),at:riyadhNow().iso,type,ref,description,user});
  store.events = store.events.slice(0,100);
}
function seed(){
  const n=riyadhNow();
  store.version=1;
  store.incidents=[
    {id:'INC-DEMO-001',createdAt:`${n.date} 07:12`,title:'تسرب مياه قرب دورات المياه',description:'تجمع مياه يحتاج معالجة عاجلة.',category:'مرافق',priority:'عاجل',location:'الدور الأول',reportedBy:'الإدارة',assignee:'فريق الصيانة',status:'قيد المعالجة',slaHours:4,dueAt:`${n.date} 11:12`,closedAt:'',closeNote:''},
    {id:'INC-DEMO-002',createdAt:`${n.date} 07:35`,title:'جهاز عرض لا يعمل',description:'تعطل جهاز العرض داخل أحد الفصول.',category:'تقنية',priority:'متوسط',location:'فصل 2/3',reportedBy:'معلم',assignee:'الدعم التقني',status:'مفتوح',slaHours:12,dueAt:`${n.date} 19:35`,closedAt:'',closeNote:''},
    {id:'INC-DEMO-003',createdAt:`${n.date} 08:05`,title:'مقبض باب مكسور',description:'يحتاج استبدال.',category:'صيانة',priority:'منخفض',location:'فصل 1/5',reportedBy:'رائد الفصل',assignee:'',status:'مفتوح',slaHours:24,dueAt:`${n.date} 23:59`,closedAt:'',closeNote:''}
  ];
  store.absences=[
    {id:'ABS-DEMO-001',date:n.date,teacher:'أحمد محمد',subject:'رياضيات',lessons:4,reason:'غياب',status:'مسجل',note:'',recordedBy:'الوكيل',at:'06:55'},
    {id:'ABS-DEMO-002',date:n.date,teacher:'سالم علي',subject:'علوم',lessons:3,reason:'مهمة رسمية',status:'مسجل',note:'',recordedBy:'الوكيل',at:'07:02'}
  ];
  store.coverage=[
    {id:'COV-DEMO-001',date:n.date,period:'1',className:'1/2',subject:'رياضيات',absentTeacher:'أحمد محمد',coverTeacher:'خالد عبدالله',status:'مغطاة',note:''},
    {id:'COV-DEMO-002',date:n.date,period:'2',className:'1/4',subject:'رياضيات',absentTeacher:'أحمد محمد',coverTeacher:'',status:'غير مغطاة',note:''},
    {id:'COV-DEMO-003',date:n.date,period:'3',className:'2/1',subject:'علوم',absentTeacher:'سالم علي',coverTeacher:'محمد حسن',status:'مغطاة',note:''},
    {id:'COV-DEMO-004',date:n.date,period:'4',className:'2/5',subject:'علوم',absentTeacher:'سالم علي',coverTeacher:'',status:'غير مغطاة',note:''}
  ];
  store.tasks=[
    {id:'TSK-DEMO-001',createdAt:`${n.date} 07:00`,title:'اعتماد مناوبة نهاية الدوام',description:'مراجعة جدول المناوبة واعتماده.',owner:'وكيل المدرسة',priority:'متوسط',department:'الإدارة',dueDate:n.date,status:'قيد التنفيذ',createdBy:'مدير المدرسة',completedAt:''},
    {id:'TSK-DEMO-002',createdAt:`${n.date} 07:10`,title:'متابعة البلاغ الصحي',description:'التأكد من معالجة البلاغ قبل الفسحة.',owner:'مسؤول السلامة',priority:'عاجل',department:'السلامة',dueDate:n.date,status:'جديدة',createdBy:'الإدارة',completedAt:''},
    {id:'TSK-DEMO-003',createdAt:`${n.date} 06:50`,title:'رفع تقرير الانضباط',description:'إقفال تقرير بداية اليوم.',owner:'شؤون الطلاب',priority:'متوسط',department:'شؤون الطلاب',dueDate:n.date,status:'مكتملة',createdBy:'الإدارة',completedAt:`${n.date} 08:15`}
  ];
  store.tardies=[
    {id:'LATE-DEMO-001',date:n.date,student:'طالب تجريبي 1',grade:'الأول متوسط',className:'2',minutes:12,note:'ازدحام',recordedBy:'الإداري',at:'07:12'},
    {id:'LATE-DEMO-002',date:n.date,student:'طالب تجريبي 2',grade:'الثاني متوسط',className:'4',minutes:18,note:'',recordedBy:'الإداري',at:'07:18'}
  ];
  store.events=[
    {id:'EV1',at:`${n.date} 08:15`,type:'مهمة',ref:'TSK-DEMO-003',description:'تم إكمال مهمة رفع تقرير الانضباط',user:'شؤون الطلاب'},
    {id:'EV2',at:`${n.date} 08:05`,type:'بلاغ',ref:'INC-DEMO-003',description:'تم تسجيل بلاغ صيانة جديد',user:'رائد الفصل'},
    {id:'EV3',at:`${n.date} 07:35`,type:'بلاغ',ref:'INC-DEMO-002',description:'تم تسجيل بلاغ تقني في فصل 2/3',user:'معلم'},
    {id:'EV4',at:`${n.date} 07:02`,type:'غياب',ref:'ABS-DEMO-002',description:'تم تسجيل غياب المعلم سالم علي',user:'الوكيل'}
  ];
}
if(!store.version || body.forceSeed===true) seed();

function slaHours(priority){return priority==='حرج'?2:priority==='عاجل'?4:priority==='منخفض'?24:12;}
function computedIncidents(){
  const nowMs = Date.now();
  return store.incidents.map(x=>{
    let slaState='ضمن الوقت';
    if(x.status!=='مغلق'){
      const due = new Date(x.dueAt.replace(' ','T')+'+03:00').getTime();
      if(Number.isFinite(due) && due < nowMs) slaState='متأخر';
    }
    return {...x,slaState};
  }).sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));
}
function dashboard(){
  const inc=computedIncidents(), today=riyadhNow().date;
  const abs=store.absences.filter(x=>x.date===today);
  const cov=store.coverage.filter(x=>x.date===today);
  const tard=store.tardies.filter(x=>x.date===today);
  const tasks=[...store.tasks].sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));
  const openInc=inc.filter(x=>x.status!=='مغلق'), critical=openInc.filter(x=>x.priority==='حرج'||x.slaState==='متأخر');
  const openTasks=tasks.filter(x=>x.status!=='مكتملة'), uncovered=cov.filter(x=>x.status!=='مغطاة');
  let level='normal',label='طبيعي';
  if(critical.length>0 || uncovered.length>=3){level='critical';label='يحتاج تدخل عاجل';}
  else if(openInc.length>=3 || uncovered.length>0 || abs.length>=2 || openTasks.filter(x=>x.priority==='عاجل'||x.priority==='حرج').length>0){level='warning';label='يحتاج متابعة';}
  const cats={};openInc.forEach(x=>cats[x.category]=(cats[x.category]||0)+1);
  return {
    success:true,generatedAt:riyadhNow().iso,dayStatus:{level,label},
    summary:{openIncidents:openInc.length,criticalIncidents:critical.length,absencesToday:abs.length,uncoveredLessons:uncovered.length,openTasks:openTasks.length,tardiesToday:tard.length},
    incidentCategories:cats,
    coverageStats:{total:cov.length,covered:cov.filter(x=>x.status==='مغطاة').length,open:uncovered.length},
    incidents:inc,absences:abs,coverage:cov,tasks,tardies:tard,recentEvents:store.events.slice(0,15)
  };
}

if(key !== API_KEY) return [{json:{success:false,message:'مفتاح SchoolPulse غير صحيح.'}}];

if(action==='ping') return [{json:{success:true,message:'SchoolPulse API is online',serverTime:riyadhNow().iso,storage:'workflow-static-data'}}];
if(action==='dashboard') return [{json:dashboard()}];

if(action==='createIncident'){
  const title=String(body.title??'').trim(),description=String(body.description??'').trim(),category=String(body.category??'أخرى').trim(),priority=String(body.priority??'متوسط').trim(),location=String(body.location??'').trim(),assignee=String(body.assignee??'').trim(),reportedBy=String(body.reportedBy??'').trim();
  if(!title||!location) return [{json:{success:false,message:'عنوان البلاغ والموقع مطلوبان.'}}];
  const hours=slaHours(priority), id=gen('INC'), createdAt=riyadhNow().iso;
  const rec={id,createdAt,title,description,category,priority,location,reportedBy,assignee,status:'مفتوح',slaHours:hours,dueAt:addHours(createdAt,hours),closedAt:'',closeNote:''};
  store.incidents.unshift(rec);event('بلاغ',id,`تم تسجيل بلاغ: ${title}`,reportedBy||'المستخدم');
  return [{json:{success:true,message:'تم تسجيل البلاغ.',incident:rec}}];
}
if(action==='updateIncident'){
  const id=String(body.id??''),r=store.incidents.find(x=>x.id===id);if(!r)return [{json:{success:false,message:'البلاغ غير موجود.'}}];
  const old=r.status;r.status=String(body.status??r.status);r.assignee=String(body.assignee??r.assignee);const note=String(body.note??'').trim();
  if(r.status==='مغلق'&&old!=='مغلق'){r.closedAt=riyadhNow().iso;r.closeNote=note;}
  event('بلاغ',id,`تحديث البلاغ ${id}: ${r.status}`,String(body.updatedBy??'المستخدم'));
  return [{json:{success:true,message:'تم تحديث البلاغ.',incident:r}}];
}
if(action==='createAbsence'){
  const teacher=String(body.teacher??'').trim(),subject=String(body.subject??'').trim(),lessons=Math.max(0,Math.min(8,Number(body.lessons??0))),reason=String(body.reason??'غياب'),recordedBy=String(body.recordedBy??'المستخدم'),note=String(body.note??'');
  if(!teacher)return [{json:{success:false,message:'اسم المعلم مطلوب.'}}];
  const id=gen('ABS'),rec={id,date:riyadhNow().date,teacher,subject,lessons,reason,status:'مسجل',note,recordedBy,at:riyadhNow().time};store.absences.unshift(rec);
  for(let i=1;i<=lessons;i++) store.coverage.push({id:gen('COV'),date:riyadhNow().date,period:String(i),className:'يحدد لاحقًا',subject,absentTeacher:teacher,coverTeacher:'',status:'غير مغطاة',note:'أنشئت تلقائيًا من تسجيل الغياب'});
  event('غياب',id,`تم تسجيل غياب المعلم ${teacher}`,recordedBy);
  return [{json:{success:true,message:'تم تسجيل الغياب وإنشاء احتياجات التغطية.',absence:rec}}];
}
if(action==='createCoverage'){
  const period=String(body.period??'').trim(),className=String(body.className??'').trim(),subject=String(body.subject??'').trim(),absentTeacher=String(body.absentTeacher??'').trim();
  if(!period||!className)return [{json:{success:false,message:'الحصة والفصل مطلوبان.'}}];
  const rec={id:gen('COV'),date:riyadhNow().date,period,className,subject,absentTeacher,coverTeacher:'',status:'غير مغطاة',note:''};store.coverage.push(rec);event('تغطية',rec.id,`تم إنشاء احتياج تغطية للحصة ${period}`,String(body.recordedBy??'المستخدم'));
  return [{json:{success:true,coverage:rec}}];
}
if(action==='updateCoverage'){
  const r=store.coverage.find(x=>x.id===String(body.id??''));if(!r)return [{json:{success:false,message:'سجل التغطية غير موجود.'}}];
  r.coverTeacher=String(body.coverTeacher??r.coverTeacher);r.status=String(body.status??r.status);r.note=String(body.note??r.note);event('تغطية',r.id,`تم تحديث تغطية الحصة ${r.period}: ${r.status}`,String(body.updatedBy??'المستخدم'));
  return [{json:{success:true,message:'تم تحديث التغطية.',coverage:r}}];
}
if(action==='createTask'){
  const title=String(body.title??'').trim(),owner=String(body.owner??'').trim();if(!title||!owner)return [{json:{success:false,message:'عنوان المهمة والمسؤول مطلوبان.'}}];
  const rec={id:gen('TSK'),createdAt:riyadhNow().iso,title,description:String(body.description??''),owner,priority:String(body.priority??'متوسط'),department:String(body.department??''),dueDate:String(body.dueDate??riyadhNow().date),status:'جديدة',createdBy:String(body.createdBy??'المستخدم'),completedAt:''};
  store.tasks.unshift(rec);event('مهمة',rec.id,`تم إنشاء مهمة: ${title}`,rec.createdBy);return [{json:{success:true,message:'تم إنشاء المهمة.',task:rec}}];
}
if(action==='updateTask'){
  const r=store.tasks.find(x=>x.id===String(body.id??''));if(!r)return [{json:{success:false,message:'المهمة غير موجودة.'}}];
  r.status=String(body.status??r.status);if(r.status==='مكتملة'&&!r.completedAt)r.completedAt=riyadhNow().iso;event('مهمة',r.id,`تم تحديث المهمة ${r.title}: ${r.status}`,String(body.updatedBy??'المستخدم'));return [{json:{success:true,message:'تم تحديث المهمة.',task:r}}];
}
if(action==='createTardy'){
  const student=String(body.student??'').trim();if(!student)return [{json:{success:false,message:'اسم الطالب مطلوب.'}}];
  const rec={id:gen('LATE'),date:riyadhNow().date,student,grade:String(body.grade??''),className:String(body.className??''),minutes:Number(body.minutes??0),note:String(body.note??''),recordedBy:String(body.recordedBy??'المستخدم'),at:riyadhNow().time};
  store.tardies.unshift(rec);event('تأخر',rec.id,`تم تسجيل تأخر الطالب ${student} (${rec.minutes} دقيقة)`,rec.recordedBy);return [{json:{success:true,message:'تم تسجيل التأخر.',tardy:rec}}];
}
if(action==='report'){
  const d=dashboard(),inc=d.incidents,tasks=d.tasks,cov=d.coverage;
  const closedInc=inc.filter(x=>x.status==='مغلق').length,completed=tasks.filter(x=>x.status==='مكتملة').length;
  const rec=[];
  if(d.summary.uncoveredLessons>0)rec.push(`توجد ${d.summary.uncoveredLessons} حصة غير مغطاة؛ يوصى بإكمال الإسناد قبل الحصة.`);
  if(d.summary.criticalIncidents>0)rec.push(`يوجد ${d.summary.criticalIncidents} بلاغ حرج أو متأخر عن SLA ويتطلب متابعة فورية.`);
  if(d.summary.openTasks>3)rec.push('عدد المهام المفتوحة مرتفع؛ يوصى بمراجعة الأولويات والمسؤولين.');
  if(d.summary.tardiesToday>=5)rec.push('مؤشر التأخر الطلابي مرتفع اليوم؛ يوصى بمتابعة أسباب التأخر المتكررة.');
  if(!rec.length)rec.push('المؤشرات التشغيلية مستقرة، مع الاستمرار في إغلاق الأعمال المفتوحة بنهاية اليوم.');
  return [{json:{success:true,date:riyadhNow().date,dayStatus:d.dayStatus,summary:{...d.summary,closedIncidents:closedInc,coveredLessons:d.coverageStats.covered,completedTasks:completed},keyEvents:d.recentEvents.slice(0,10),priorityIncidents:inc.filter(x=>x.status!=='مغلق'&&(x.priority==='حرج'||x.priority==='عاجل'||x.slaState==='متأخر')).slice(0,10),recommendations:rec}}];
}
if(action==='resetDemo'){seed();event('النظام','RESET','تمت إعادة بيانات SchoolPulse التجريبية',String(body.staff??'المستخدم'));return [{json:{success:true,message:'تمت إعادة بيانات التجربة.'}}];}

return [{json:{success:false,message:'الإجراء المطلوب غير مدعوم.'}}];
